let lastPerformanceDeletion=null;
function deletionRender(){render();renderReview();drawPreview();$('commitImport').disabled=!importPreview.some(e=>!e.duplicate)&&!(importPreview.staffChanges||[]).length;if(reviewSelection&&!state.entries.some(e=>e.id===reviewSelection)&&!importPreview.some(e=>e.id===reviewSelection)){$('reviewPanel').classList.add('hidden');reviewSelection=null}if(editing&&!state.entries.some(e=>e.id===editing))reset()}
function removePerformance(id,kind){const source=kind==='preview'?importPreview:state.entries,entry=source.find(e=>e.id===id);if(!entry||entry.month!==$('month').value)return false;const title=[entry.teacher,entry.student,ruleBy(entry.rule)?.item||entry.raw?.type||'绩效记录'].filter(Boolean).join(' / ');if(!confirm('删除“'+title+'”？这条记录将从当前计算和报表中移除，员工版本名单保留。当前页面内可撤销最近一次删除。'))return false;
 const savedBefore=state.entries,previewBefore=importPreview.slice(),savedRemoved=[],previewRemoved=[];const same=e=>e.id===id||(kind==='saved'&&e.month===entry.month&&entry.sourceKey&&e.sourceKey===entry.sourceKey);if(kind==='saved'){state.entries=state.entries.filter((e,i)=>{if(e.id===id){savedRemoved.push({entry:e,index:i});return false}return true})}for(let i=importPreview.length-1;i>=0;i--)if(same(importPreview[i]))previewRemoved.unshift({entry:importPreview.splice(i,1)[0],index:i});
 try{if(kind==='saved')save()}catch(err){state.entries=savedBefore;importPreview.splice(0,importPreview.length,...previewBefore);toast('删除未保存：'+err.message);return false}
 lastPerformanceDeletion={campus:campusStore.active().id,month:$('month').value,savedRemoved,previewRemoved,previewRef:importPreview};deletionRender();$('deleteUndo').classList.remove('hidden');$('reportUndoDelete').classList.remove('hidden');$('deleteUndoText').textContent='已删除：'+title+'。';toast('已删除，合计和报表已更新');return true}
function undoPerformanceDeletion(){const item=lastPerformanceDeletion;if(!item||item.campus!==campusStore.active().id||item.month!==$('month').value)return false;if(!item.savedRemoved.length&&item.previewRef!==importPreview){lastPerformanceDeletion=null;$('deleteUndo').classList.add('hidden');$('reportUndoDelete').classList.add('hidden');toast('预览已重新生成，请在新预览中核对记录');return false}const savedBefore=state.entries.slice(),previewBefore=importPreview.slice();for(const x of item.savedRemoved)if(!state.entries.some(e=>e.id===x.entry.id))state.entries.splice(Math.min(x.index,state.entries.length),0,x.entry);if(item.previewRef===importPreview)for(const x of item.previewRemoved)if(!importPreview.some(e=>e.id===x.entry.id))importPreview.splice(Math.min(x.index,importPreview.length),0,x.entry);
 try{if(item.savedRemoved.length)save()}catch(err){state.entries=savedBefore;importPreview.splice(0,importPreview.length,...previewBefore);toast('撤销未保存：'+err.message);return false}lastPerformanceDeletion=null;deletionRender();$('deleteUndo').classList.add('hidden');$('reportUndoDelete').classList.add('hidden');toast('已恢复最近一次删除的绩效记录');return true}
for(const id of ['reviewBody','previewBody','feeReport','signReport'])$(id).addEventListener('click',e=>{const button=e.target.closest('[data-performance-delete]');if(button)removePerformance(button.dataset.performanceDelete,button.dataset.deleteKind)});
$('undoPerformanceDelete').onclick=undoPerformanceDeletion;$('reportUndoDelete').onclick=undoPerformanceDeletion;
const refreshBeforeDeletion=refreshCampusState;refreshCampusState=function(){lastPerformanceDeletion=null;$('deleteUndo').classList.add('hidden');$('reportUndoDelete').classList.add('hidden');refreshBeforeDeletion()};
$('month').addEventListener('change',()=>{lastPerformanceDeletion=null;$('deleteUndo').classList.add('hidden');$('reportUndoDelete').classList.add('hidden')});
